class QueryError(Exception):
    pass


# ---------------------------------------------------------------- import
def _norm(h):
    return re.sub(r'\s+', ' ', str(h or '')).strip().lower()

_HEADMAP = {_norm(c): c for c in COLUMNS}


def parse_dt(s):
    s = str(s or '').strip()
    for f in (DT_FMT, '%d-%m-%Y %H:%M', '%d-%m-%Y', '%d/%m/%Y %H:%M:%S', '%d/%m/%Y', '%Y-%m-%d %H:%M:%S', '%Y-%m-%d'):
        try:
            return datetime.strptime(s, f)
        except ValueError:
            pass
    return None


def parse_fee(v):
    if v is None or v == '':
        return 0
    if isinstance(v, (int, float)):
        return int(v) if float(v).is_integer() else float(v)
    try:
        x = float(str(v).replace(',', '').strip())
        return int(x) if x.is_integer() else x
    except ValueError:
        return 0


def _cell_text(v):
    if v is None:
        return ''
    if isinstance(v, datetime):
        return v.strftime(DT_FMT)
    if isinstance(v, date):
        return v.strftime('%d-%m-%Y')
    if isinstance(v, float) and v.is_integer():
        v = int(v)
    return str(v).strip()


def _raw_rows(path):
    ext = os.path.splitext(path)[1].lower()
    if ext in ('.csv', '.txt'):
        for enc in ('utf-8-sig', 'cp1252', 'latin-1'):
            try:
                with open(path, newline='', encoding=enc) as f:
                    return list(csv.reader(f))
            except UnicodeDecodeError:
                continue
    if ext in ('.xlsx', '.xlsm'):
        import openpyxl
        wb = openpyxl.load_workbook(path, read_only=True, data_only=True)
        ws = wb['Receipts'] if 'Receipts' in wb.sheetnames else wb.worksheets[0]
        rows = [list(r) for r in ws.iter_rows(values_only=True)]
        wb.close()
        return rows
    if ext == '.xls':
        raise ValueError('Old .xls files are not supported. Open it in Excel and Save As .xlsx or .csv.')
    raise ValueError('Unsupported file type: ' + ext)


def load_file(path):
    raw = _raw_rows(path)
    # find header row
    hi = next((i for i, r in enumerate(raw[:20]) if 'receipt no.' in [_norm(c) for c in r]), None)
    if hi is None:
        raise ValueError('Could not find the "Receipt No." header row in ' + os.path.basename(path))
    idx = {}
    for j, h in enumerate(raw[hi]):
        c = _HEADMAP.get(_norm(h))
        if c and c not in idx:
            idx[c] = j
    out = []
    for r in raw[hi + 1:]:
        rec = {c: (r[idx[c]] if c in idx and idx[c] < len(r) else None) for c in COLUMNS}
        rn = _cell_text(rec['Receipt No.'])
        if not rn:            # blank rows and the grand-total row are skipped
            continue
        row = {c: _cell_text(rec[c]) for c in COLUMNS}
        row['_fee'] = parse_fee(rec['Service Fee'])
        row['Service Fee'] = row['_fee']
        row['_dt'] = parse_dt(row['Receipt Generated At'])
        out.append(row)
    return out


def load_files(paths):
    seen, rows = set(), []
    for p in paths:
        for r in load_file(p):
            if r['Receipt No.'] not in seen:
                seen.add(r['Receipt No.'])
                rows.append(r)
    return rows


# ---------------------------------------------------------------- query language
def _resolve_field(words):
    name = _norm(' '.join(words))
    if name in ALIASES:
        return ALIASES[name]
    if name in _HEADMAP:
        return _HEADMAP[name]
    hits = [c for c in COLUMNS if name and name in c.lower()]
    if len(hits) == 1:
        return hits[0]
    raise QueryError('Unknown field: "%s". Use a column name such as Service Name, Service Fee, Staff Name.' % ' '.join(words))


_SYM = {'=', '==', '!=', '>', '>=', '<', '<='}
_WORDOPS = {'contains', 'startswith', 'endswith', 'like'}


def _compare(field, op, val, row):
    if field == 'Service Fee':
        try:
            a, b = float(row['_fee']), float(val)
        except ValueError:
            raise QueryError('Service Fee needs a number, got "%s"' % val)
    elif field == 'Receipt Generated At' and op in ('>', '>=', '<', '<=', '=', '==', '!='):
        b = parse_dt(val)
        if b is None:
            raise QueryError('Date should look like 25-09-2026 or 25-09-2026 14:30:00')
        a = row['_dt']
        if a is None:
            return False
        if op in ('=', '==', '!=') and ' ' not in val.strip():
            eq = a.date() == b.date()
            return eq if op != '!=' else not eq
        if op in ('<=',) and ' ' not in val.strip():
            b = datetime.combine(b.date(), time(23, 59, 59))
        if op in ('>',) and ' ' not in val.strip():
            b = datetime.combine(b.date(), time(23, 59, 59))
    else:
        a, b = str(row[field]).casefold(), str(val).casefold()
    if op in ('=', '=='):
        return a == b
    if op == '!=':
        return a != b
    if op == '>':
        return a > b
    if op == '>=':
        return a >= b
    if op == '<':
        return a < b
    if op == '<=':
        return a <= b
    if op == 'contains':
        return b in a
    if op == 'startswith':
        return a.startswith(b)
    if op == 'endswith':
        return a.endswith(b)
    if op == 'like':
        return fnmatch.fnmatchcase(a, b)
    raise QueryError('Bad operator ' + op)


def compile_query(q):
    """Examples:  Service Name contains DDR and Service Fee >= 100
                  (kendra = "CPSC Central Amritsar" or type = PSOC) and not staff contains Navraj"""
    q = (q or '').strip()
    if not q:
        return lambda r: True
    toks = re.findall(r'"[^"]*"|\'[^\']*\'|\(|\)|>=|<=|!=|==|=|>|<|[^\s()=<>!]+', q)
    pos = [0]

    def peek():
        return toks[pos[0]] if pos[0] < len(toks) else None

    def take():
        t = peek(); pos[0] += 1; return t

    def is_kw(t, *k):
        return t is not None and t.lower() in k

    def expr():
        left = term()
        while is_kw(peek(), 'or'):
            take(); right = term(); l, r = left, right
            left = (lambda l, r: lambda row: l(row) or r(row))(l, r)
        return left

    def term():
        left = factor()
        while is_kw(peek(), 'and'):
            take(); right = factor(); l, r = left, right
            left = (lambda l, r: lambda row: l(row) and r(row))(l, r)
        return left

    def factor():
        t = peek()
        if t is None:
            raise QueryError('Query ended unexpectedly')
        if is_kw(t, 'not'):
            take(); f = factor(); return lambda row: not f(row)
        if t == '(':
            take(); e = expr()
            if take() != ')':
                raise QueryError('Missing closing )')
            return e
        words = []
        while peek() is not None and peek() not in _SYM and not is_kw(peek(), *_WORDOPS) and not is_kw(peek(), 'not') \
                and peek() not in ('(', ')') and not is_kw(peek(), 'and', 'or'):
            words.append(take())
        negate = False
        if is_kw(peek(), 'not'):
            take(); negate = True
        op = peek()
        if op is None or not (op in _SYM or op.lower() in _WORDOPS):
            raise QueryError('Expected an operator (=, !=, >, >=, <, <=, contains, startswith, endswith, like) after "%s"' % ' '.join(words))
        take(); op = op.lower()
        if not words:
            raise QueryError('Missing field name before ' + op)
        field = _resolve_field(words)
        vt = peek()
        if vt is None:
            raise QueryError('Missing value after ' + op)
        if vt[0] in '"\'':
            take(); val = vt[1:-1]
        else:
            vw = []
            while peek() is not None and peek() != ')' and not is_kw(peek(), 'and', 'or'):
                vw.append(take())
            val = ' '.join(vw)
        def cond(row, field=field, op=op, val=val, negate=negate):
            res = _compare(field, op, val, row)
            return (not res) if negate else res
        return cond

    fn = expr()
    if peek() is not None:
        raise QueryError('Unexpected "%s" in query' % peek())
    return fn


# ---------------------------------------------------------------- filter / sort

def norm_service(s):
    s = re.sub(r'[\u2010-\u2015\u2212]', '-', str(s or ''))
    return re.sub(r'\s+', ' ', s).strip().casefold()


def parse_order(text):
    """Lines are 'Service Name' or 'Service Name | Short Name'. Returns the service names in order."""
    return [l.split('|')[0].strip() for l in (text or '').splitlines() if l.split('|')[0].strip()]


def parse_shorts(text, base=None):
    """Short-name map {normalized service name: short}. Lines without '|' fall back to the built-in short name."""
    base = {norm_service(k): v for k, v in (DEFAULT_SHORTS if base is None else base).items()}
    out = {}
    for l in (text or '').splitlines():
        parts = [p.strip() for p in l.split('|')]
        if not parts[0]:
            continue
        k = norm_service(parts[0])
        out[k] = parts[1] if len(parts) > 1 and parts[1] else base.get(k, '')
    return {k: v for k, v in out.items() if v}


def order_lines(names, shorts):
    return '\n'.join(n + (' | ' + shorts[norm_service(n)] if shorts.get(norm_service(n)) else '') for n in names)


def load_order_file(path):
    """Column A = service name, column B (optional) = short name. Returns lines 'name | short'."""
    ext = os.path.splitext(path)[1].lower()
    rows = []
    if ext in ('.xlsx', '.xlsm'):
        import openpyxl
        wb = openpyxl.load_workbook(path, read_only=True, data_only=True)
        for ws in wb.worksheets:
            for r in ws.iter_rows(values_only=True):
                if r and r[0] is not None and str(r[0]).strip():
                    rows.append((str(r[0]).strip(), str(r[1]).strip() if len(r) > 1 and r[1] else ''))
        wb.close()
    else:
        for r in _raw_rows(path):
            if r and r[0].strip():
                rows.append((r[0].strip(), r[1].strip() if len(r) > 1 else ''))
    return [n + (' | ' + sh if sh else '') for n, sh in rows if norm_service(n) != 'service name']


def order_rank(order):
    rank = {}
    for i, n in enumerate(order or []):
        rank.setdefault(norm_service(n), i)
    return rank

def apply_filters(rows, f):
    """f keys: date_from/date_to (date), services (set), kendras, types, staffs (sets),
    fee_min/fee_max, text, query, real_date_sort (bool)"""
    qfn = compile_query(f.get('query'))
    text = (f.get('text') or '').strip().casefold()
    df, dt_ = f.get('date_from'), f.get('date_to')
    out = []
    for r in rows:
        if df or dt_:
            d = r['_dt']
            if d is None:
                continue
            if df and d.date() < df: continue
            if dt_ and d.date() > dt_: continue
        if f.get('services') and r['Service Name'] not in f['services']: continue
        if f.get('kendras') and r['Saanjh Kendra'] not in f['kendras']: continue
        if f.get('types') and r['Saanjh Kendra Type'] not in f['types']: continue
        if f.get('staffs') and r['Receipt Generated By'] not in f['staffs']: continue
        if f.get('fee_min') not in (None, '') and r['_fee'] < float(f['fee_min']): continue
        if f.get('fee_max') not in (None, '') and r['_fee'] > float(f['fee_max']): continue
        if text and text not in ' '.join(str(r[c]) for c in COLUMNS).casefold(): continue
        if not qfn(r): continue
        out.append(r)
    rank = order_rank(f.get('order'))
    big = len(rank) + 1
    def key(r):
        k = (rank.get(norm_service(r['Service Name']), big), norm_service(r['Service Name']) if r['Service Name'] else '')
        if f.get('real_date_sort'):
            return k + (r['_dt'] or datetime.min,)
        return k + (r['Receipt Generated At'],)     # text sort, same as the sample output
    out.sort(key=key)
    return out


def out_table(rows, cols=None):
    """Rows as lists, limited to `cols` (names from ALL_OUT, in standard order). Default = the 9 sample columns."""
    cols = cols or OUT_COLS
    res = []
    for i, r in enumerate(rows):
        res.append([i + 1 if c == 'sr no' else (r['_fee'] if c == 'Service Fee' else r[c]) for c in cols])
    return res


def clean_cols(cols):
    """Keep only valid names, in standard ALL_OUT order."""
    cols = set(cols or OUT_COLS)
    out = [c for c in ALL_OUT if c in cols]
    return out or list(OUT_COLS)


# ---------------------------------------------------------------- summary
def parse_rules(text):
    rules = []
    for line in (text or '').splitlines():
        line = line.strip()
        if not line or ':' not in line:
            continue
        label, pats = line.split(':', 1)
        rules.append((label.strip(), [p.strip() for p in pats.split(',') if p.strip()]))
    return rules


def summarize(rows, rules_text=None, all_services=False, order=None, shorts=None):
    """Returns list of (name, count, fee, total); fee is a number or 'Mixed'.
    Names are SHORT names; services that share a short name are merged into one line.
    Rules mode : only the services matched by the rules (Label: pattern, pattern)  - used when all_services is False
    All mode   : every service, in your custom order (rules can still merge extra groups)."""
    shorts = shorts if shorts is not None else {norm_service(k): v for k, v in DEFAULT_SHORTS.items()}
    short = lambda n: shorts.get(norm_service(n)) or n
    rules = parse_rules(rules_text)
    def match(r, pats):
        n = r['Service Name'].casefold()
        return any(fnmatch.fnmatchcase(n, p.casefold()) for p in pats)
    rank = order_rank(order); big = len(rank) + 1
    rk = lambda r: rank.get(norm_service(r['Service Name']), big)
    used, tmp = set(), []
    for label, pats in rules:
        sel = [r for r in rows if match(r, pats) and id(r) not in used]
        if sel or not all_services:
            used.update(id(r) for r in sel)
            tmp.append((min([rk(r) for r in sel] or [big]), label.casefold(), short(label), sel))
    if all_services:
        rest = {}
        for r in rows:
            if id(r) not in used:
                rest.setdefault(short(r['Service Name']), []).append(r)
        for n, sel in rest.items():
            tmp.append((min(rk(r) for r in sel), n.casefold(), n, sel))
        tmp.sort(key=lambda t: (t[0], t[1]))
    else:
        # default view: short-name groups of everything is too long, so show rule lines only
        pass
    # merge lines that ended up with the same label (e.g. two rules mapping to one short name)
    merged = {}
    for _, _, label, sel in tmp:
        merged.setdefault(label.casefold(), [label, []])[1].extend(sel)
    out = []
    for label, sel in merged.values():
        fees = {r['_fee'] for r in sel}
        fee = fees.pop() if len(fees) == 1 else ('Mixed' if fees else 0)
        out.append((label, len(sel), fee, sum(r['_fee'] for r in sel)))
    return out


def range_text(rows, f):
    ds = [r['_dt'].date() for r in rows if r['_dt']]
    a = f.get('date_from') or (min(ds) if ds else None)
    b = f.get('date_to') or (max(ds) if ds else None)
    fm = lambda d: d.strftime('%d-%m-%Y') if d else '  '
    return 'Service Details from Date %s to date %s' % (fm(a), fm(b))


# ---------------------------------------------------------------- Excel export (formatted for A4 landscape print)
WIDTHS = {'sr no': 7, 'Receipt No.': 26, 'Staff Name': 28, 'Service Name': 32, 'Application UID': 22, 'Service Fee': 10,
          'District': 12, 'Saanjh Kendra Type': 12, 'Saanjh Kendra': 24, 'Receipt Generated By': 28,
          'Receipt Generated At': 20, 'Applicant Name': 24, 'Relation Type': 10, 'Relative Name': 24,
          'Applicant Mobile': 15, 'Applicant Email': 30}


def export_excel(path, rows, summary, title_text, cols=None):
    from openpyxl import Workbook
    from openpyxl.styles import Font, Alignment, Border, Side, PatternFill
    from openpyxl.utils import get_column_letter as L
    cols = clean_cols(cols)
    wb = Workbook(); ws = wb.active; ws.title = 'Receipts'
    font = Font(name='Calibri', size=12); bold = Font(name='Calibri', size=12, bold=True)
    thin = Side(style='thin'); border = Border(left=thin, right=thin, top=thin, bottom=thin)
    wrap = Alignment(wrap_text=True, vertical='top')
    center = Alignment(wrap_text=True, vertical='top', horizontal='center')
    head_fill = PatternFill('solid', fgColor='FFD9A8')
    table = out_table(rows, cols)
    nc = len(cols); n = len(table) + 1
    ws.append(cols)
    for r in table:
        ws.append(r)
    has_fee = 'Service Fee' in cols
    if has_fee:
        tr = n + 1; fc = cols.index('Service Fee') + 1
        ws.cell(tr, fc, '=SUM(%s2:%s%d)' % (L(fc), L(fc), n) if n > 1 else 0).font = bold
        if fc > 1:
            ws.cell(tr, fc - 1, 'Total').font = bold
        last = tr
    else:
        last = n
    for row in ws.iter_rows(min_row=1, max_row=last, min_col=1, max_col=nc):
        for c in row:
            if c.font is None or not c.font.b:
                c.font = font
            c.border = border; c.alignment = center if cols[c.column - 1] == 'sr no' else wrap
    for c in ws[1][:nc]:
        c.font = bold; c.fill = head_fill
    # summary block (4 columns, one empty column after the table) like the sample
    s0 = nc + 2
    ws.merge_cells(start_row=2, start_column=s0, end_row=2, end_column=s0 + 3)
    ws.cell(2, s0, title_text).font = bold; ws.cell(2, s0).alignment = center
    for j, h in enumerate(['Service Name', 'Service Count', 'Service Fee', 'Total']):
        c = ws.cell(3, s0 + j, h); c.font = bold; c.fill = head_fill
    r0 = 4
    for i, (name, cnt, fee, tot) in enumerate(summary):
        rr = r0 + i
        ws.cell(rr, s0, name); ws.cell(rr, s0 + 1, cnt); ws.cell(rr, s0 + 2, fee)
        ws.cell(rr, s0 + 3, '=%s%d*%s%d' % (L(s0 + 1), rr, L(s0 + 2), rr) if isinstance(fee, (int, float)) else tot)
    rt = r0 + len(summary)
    ws.cell(rt, s0, 'TOTAL').font = bold
    ws.cell(rt, s0 + 3, '=SUM(%s%d:%s%d)' % (L(s0 + 3), r0, L(s0 + 3), rt - 1) if summary else 0).font = bold
    for row in ws.iter_rows(min_row=2, max_row=rt, min_col=s0, max_col=s0 + 3):
        for c in row:
            c.border = border; c.alignment = wrap if c.row != 2 else center
            if not c.font.b:
                c.font = font
    for j, c in enumerate(cols):
        ws.column_dimensions[L(j + 1)].width = WIDTHS.get(c, 18)
    ws.column_dimensions[L(nc + 1)].width = 3
    for col, w in zip(range(s0, s0 + 4), [30, 11, 11, 12]):
        ws.column_dimensions[L(col)].width = w
    # print setup: A4, landscape, minimum margins 0.03", fit to 1 page wide, repeat header row
    ws.page_setup.paperSize = ws.PAPERSIZE_A4
    ws.page_setup.orientation = 'landscape'
    ws.page_setup.fitToWidth = 1; ws.page_setup.fitToHeight = 0
    ws.sheet_properties.pageSetUpPr.fitToPage = True
    m = ws.page_margins
    m.left = m.right = m.top = m.bottom = 0.03; m.header = m.footer = 0.03
    ws.print_title_rows = '1:1'
    ws.freeze_panes = 'A2'
    wb.save(path)


# ---------------------------------------------------------------- Print (HTML -> browser print dialog)
def build_print_html(rows, summary, title_text, cols=None, auto_print=True):
    e = html.escape
    cols = clean_cols(cols)
    table = out_table(rows, cols)
    total = sum(r['_fee'] for r in rows)
    body = ''.join('<tr>' + ''.join('<td class="c">%s</td>' % e(str(v)) if cols[i] == 'sr no' else '<td>%s</td>' % e(str(v))
                                    for i, v in enumerate(r)) + '</tr>' for r in table)
    if 'Service Fee' in cols:
        fi = cols.index('Service Fee')
        cells = ['<td></td>'] * len(cols)
        cells[fi] = '<td>%s</td>' % e(str(total))
        if fi > 0: cells[fi - 1] = '<td>Total</td>'
        body += '<tr class="b">%s</tr>' % ''.join(cells)
    head = ''.join('<th>%s</th>' % e(h) for h in cols)
    srows = ''.join('<tr><td>%s</td><td>%s</td><td>%s</td><td>%s</td></tr>' % (e(n), c, f, t) for n, c, f, t in summary)
    gt = sum(s[3] for s in summary)
    return '''<!DOCTYPE html><html><head><meta charset="utf-8"><title>Receipts Report</title><style>
@page { size: A4 landscape; margin: 0.03in; }
html, body { margin: 0; padding: 0; font-family: Calibri, Arial, sans-serif; font-size: 12pt; color: #000; }
.wrap { display: flex; align-items: flex-start; gap: 6px; }
table { border-collapse: collapse; }
.main { flex: 1 1 auto; table-layout: auto; }
.side { flex: 0 0 auto; width: 3.1in; }
th, td { border: 1px solid #000; padding: 1px 3px; vertical-align: top; font-size: 12pt;
         white-space: normal; overflow-wrap: anywhere; word-break: break-word; }
th { background: #FFD9A8; font-weight: bold; text-align: left; }
thead { display: table-header-group; } tr { page-break-inside: avoid; }
td.c { text-align: center; } tr.b td { font-weight: bold; }
.side th, .side td { width: auto; } .st { text-align: center; font-weight: bold; border: 1px solid #000; padding: 2px; }
</style></head><body><div class="wrap">
<table class="main"><thead><tr>%s</tr></thead><tbody>%s</tbody></table>
<div class="side"><div class="st">%s</div><table class="side" style="width:100%%"><thead><tr><th>Service Name</th><th>Service Count</th><th>Service Fee</th><th>Total</th></tr></thead>
<tbody>%s<tr class="b"><td>TOTAL</td><td></td><td></td><td>%s</td></tr></tbody></table></div>
</div>%s</body></html>''' % (head, body, e(title_text), srows, gt,
                              '<script>window.onload=function(){setTimeout(function(){window.print();},400);};</script>' if auto_print else '')


def write_print_html(rows, summary, title_text, cols=None):
    fd, p = tempfile.mkstemp(suffix='.html', prefix='receipts_print_')
    with os.fdopen(fd, 'w', encoding='utf-8') as f:
        f.write(build_print_html(rows, summary, title_text, cols))
    return p
